// BlockName returns the block name for a default state id.
func BlockName(b Block) (string, bool) {
	n, ok := blockNames[b]
	return n, ok
}

// BlockNames lists every block name, sorted. The command
// completion engine and /setblock use it as the name universe.
func BlockNames() []string {
	out := make([]string, 0, len(blockNames))
	for _, name := range blockNames {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}
